<x-theme::section data-theme-block="category_grid"><x-theme::container>@if(!empty($settings['title']))<x-theme::heading :level="2" class="theme-section-title">{{ $settings['title'] }}</x-theme::heading>@endif<div class="theme-grid theme-category-grid" style="--category-columns:{{ min(6, max(2, (int) ($settings['columns'] ?? 4))) }}">@forelse($categories as $category)<x-theme::category-card :category="$category" class="theme-category-card--{{ $settings['image_style'] ?? 'rounded' }}" />@empty<x-theme::empty-state title="دسته‌بندی‌ای یافت نشد" />@endforelse</div></x-theme::container></x-theme::section>
